"""Where the ventilation grilles go: a concept, generated by rule from room type, with explicit overrides from the spec.

This is the one source for the grilles. 02 calls layout() and writes build/vents.json; the 3D scene, the configurator's rooms
and the 2D plan all read that file, so they can't disagree. It needs no Blender and reads no drawing: only the derived plan.
Nothing here is SSMC's mechanical design. The sheets show no grilles, ducts or air data.
"""
import math

import numpy as np
from shapely.geometry import LineString, Point, Polygon, box
from shapely.ops import unary_union
from shapely.prepared import prep


def room_type(name, spec):
    """The first rule in ventilation.room_types whose match list holds this label, or None."""
    for rule in spec["ventilation"]["room_types"]:
        if any(name == m or (m.endswith("*") and name.startswith(m[:-1])) for m in rule["match"]):
            return rule
    return None


def flood(space, at, radius, step=0.1):
    """Floor within radius of a point, measured round walls. Small rooms in the merged corridor space have no polygon of their own."""
    near = space.intersection(Point(at).buffer(radius + step))
    reach = Point(at).buffer(step)
    for _ in range(round(radius / step)):
        reach = reach.buffer(step).intersection(near)
    parts = list(getattr(reach, "geoms", [reach]))
    return min(parts, key=Point(at).distance) if parts else Polygon()


class Placer:
    """Finds the nearest spot to a target where a grille clears the walls, what's on the ceiling and other grilles."""

    def __init__(self, spec, keepout):
        V = spec["ventilation"]
        self.grilles = V["grilles"]
        self.clear = V["clearance"]
        self.keepout = keepout.buffer(self.clear["ceiling_items"]) if not keepout.is_empty else keepout
        self.keep_prep = prep(self.keepout)
        self.placed = []
        self.step = V["search_step"]

    def rect(self, kind, x, y):
        w, d = self.grilles[kind]["size"]
        return box(x - w / 2, y - d / 2, x + w / 2, y + d / 2)

    def fits(self, kind, x, y, zone_inset):
        r = self.rect(kind, x, y)
        if not zone_inset.contains(r) or self.keep_prep.intersects(r):
            return False
        gap = self.clear["grilles"]
        return all(r.distance(o) >= gap for o in self.placed)

    def place(self, kind, zone, target):
        """Returns (x, y), or None if nothing in the zone fits."""
        inset = zone.buffer(-self.clear["walls"])
        if inset.is_empty:
            return None
        x0, y0, x1, y1 = inset.bounds
        s = self.step
        xs = np.arange(round(x0 / s) * s, x1 + s, s)
        ys = np.arange(round(y0 / s) * s, y1 + s, s)
        gx, gy = np.meshgrid(xs, ys)
        order = np.argsort(((gx - target[0]) ** 2 + (gy - target[1]) ** 2).ravel())
        px, py = gx.ravel(), gy.ravel()
        inset_prep = prep(inset)
        w, d = self.grilles[kind]["size"]
        for i in order:
            x, y = float(px[i]), float(py[i])
            r = box(x - w / 2, y - d / 2, x + w / 2, y + d / 2)
            if not inset_prep.contains(r) or self.keep_prep.intersects(r):
                continue
            if any(r.distance(o) < self.clear["grilles"] for o in self.placed):
                continue
            self.placed.append(r)
            return round(x, 3), round(y, 3)
        return None


def counts(rule, area, height, spec):
    """How many grilles of each kind this room's air needs, and its air in l/s. A rule can fix a count outright."""
    G = spec["ventilation"]["grilles"]
    air = rule["ach_total"] * area * height / 3.6 if rule.get("ach_total") else 0.0
    out = {}
    for kind in rule["air"]:
        fixed = rule.get("count", {}).get(kind)
        margin = rule.get("exhaust_margin", 1.0) if kind == "exhaust" else 1.0
        out[kind] = fixed if fixed is not None else max(1, math.ceil(air * margin / G[kind]["capacity_ls"]))
    return out, air


def layout(spec, plan, spaces, rooms, keepout, height):
    """Returns {"vents": [...], "zones": [...]}.

    spaces: [{"names", "labels", "poly"}] as 02 builds them. rooms: its rooms_index, with the labels from planlib.label_rooms.
    keepout: what the grilles must clear on the ceiling plane.
    """
    V = spec["ventilation"]
    placer = Placer(spec, keepout)
    vents, zones = [], []
    used_overrides = set()

    def put(kind, zone_id, zone_poly, target, rule, basis="rule", required=True):
        ov = next((o for i, o in enumerate(V.get("overrides", [])) if o["zone"] == zone_id and o["kind"] == kind and i not in used_overrides), None)
        if ov is not None:
            used_overrides.add(V["overrides"].index(ov))
            spot, basis = tuple(ov["at"]), "override"
            placer.placed.append(placer.rect(kind, *spot))
        else:
            spot = placer.place(kind, zone_poly, target)
        if spot is None:
            if required:
                raise SystemExit(f"ventilation: no room for a {kind} grille in {zone_id} near {np.round(target, 2).tolist()}")
            return None
        vents.append({"id": f"{zone_id}_{kind}_{sum(1 for v in vents if v['zone'] == zone_id and v['kind'] == kind)}",
                      "kind": kind, "zone": zone_id, "type": rule["type"], "at": list(spot), "size": V["grilles"][kind]["size"], "basis": basis})
        return spot

    def add_zone(zone_id, name, rule, poly, air, n, label_at):
        zones.append({"id": zone_id, "name": name, "type": rule["type"], "area_m2": round(poly.area, 1), "air_ls": round(air), "grilles": n, "label_at": [round(float(v), 3) for v in label_at]})

    # ---------------------------------------------------------------- patient rooms, placed from the bed
    room_at = {}
    for r in rooms:
        poly = next(s["poly"] for s in spaces if s["poly"].contains(Point(r["label_at"])))
        room_at[r["label"]] = poly
        iso = any("ISOLATION" in n for n in r["names"])
        rule = room_type("ICU ISOLATION PATIENT ROOM" if iso else "ICU PATIENT ROOM", spec)
        n, air = counts(rule, poly.area, height, spec)
        head, foot = np.array(r["head"]), np.array(r["foot_dir"])
        cross = np.array([foot[1], -foot[0]])
        front, inward = np.array(r["front"]), np.array(r["front_normal_in"])
        if iso:
            # clean air in by the door, drawn across the room and out over the patient's head
            for i in range(n["supply"]):
                put("supply", r["label"], poly, front + inward * (1.0 + 1.6 * i), rule)
            for i in range(n["exhaust"]):
                sgn = (-1, 1)[i % 2]
                put("exhaust", r["label"], poly, head + foot * 0.05 + cross * sgn * 0.35, rule)
        else:
            for i in range(n["supply"]):
                put("supply", r["label"], poly, head + foot * (3.0 + 1.6 * i), rule)
            for i in range(n["return"]):
                sgn = (-1, 1)[i % 2]
                put("return", r["label"], poly, head + foot * 0.5 + cross * sgn * 1.6, rule)
        add_zone(r["label"], "Isolation room" if iso else "Patient room", rule, poly, air, n, r["label_at"])

    # ---------------------------------------------------------------- the isolation suites: ante room and toilet, keyed to their room
    iso_rooms = [r for r in rooms if any("ISOLATION" in n for n in r["names"])]
    merged = []
    for si, s in enumerate(spaces):
        if any(n in ("ICU PATIENT ROOM", "ICU ISOLATION PATIENT ROOM") for n in s["names"]):
            continue
        if len(s["names"]) == 1:
            name = s["names"][0]
            rule = room_type(name, spec)
            if rule is None or not rule["air"] or rule["type"] == "corridor":
                continue
            at = np.array(s["labels"][0])
            suite = None
            if name in ("ANTE", "TOILET"):
                suite = next((r for r in iso_rooms if room_at[r["label"]].distance(s["poly"]) < V["suite_gap"]), None)
            if name == "TOILET" and suite is not None:
                rule = room_type("ISOLATION TOILET", spec)
            zone_id = f"{suite['label']}_{name.lower()}" if suite else f"{name.lower().replace(' ', '_').replace('.', '')}_{si}"
            n, air = counts(rule, s["poly"].area, height, spec)
            c = np.array(s["poly"].representative_point().coords[0])
            if name == "ANTE" and suite is not None:
                inner = np.array(suite["front"])  # exhaust by the room's door, supply by the corridor's: air moves toward the room
                far = np.array(max(s["poly"].exterior.coords, key=lambda q: math.dist(q, inner)))
                put("supply", zone_id, s["poly"], far, rule)
                put("exhaust", zone_id, s["poly"], inner, rule)
            else:
                for kind in rule["air"]:
                    for i in range(n[kind]):
                        target = at if kind == "supply" else c
                        if len(rule["air"]) > 1 and kind != "supply":
                            target = np.array(max(s["poly"].exterior.coords, key=lambda q: math.dist(q, at)))
                        put(kind, zone_id, s["poly"], target, rule)
            add_zone(zone_id, name.title(), rule, s["poly"], air, n, at)
        elif s["names"]:
            merged.append(s)

    # ---------------------------------------------------------------- rooms with no polygon of their own: a local zone around each label
    taken = []
    for s in merged:
        for name, at in zip(s["names"], s["labels"]):
            rule = room_type(name, spec)
            if rule is None or not rule["air"] or rule["type"] == "corridor":
                continue
            zone = flood(s["poly"], at, rule.get("zone_radius", V["zone_radius"]))
            if zone.is_empty:
                continue
            taken.append(zone)
            zone_id = f"{name.lower().replace(' ', '_').replace('.', '')}_{round(at[0])}_{round(at[1])}"
            n, air = counts(rule, zone.area, height, spec)
            c = np.array(at)
            placed_any = False
            for kind in rule["air"]:
                for i in range(n[kind]):
                    target = c
                    if kind != "supply" and "supply" in rule["air"]:
                        target = np.array(max(zone.exterior.coords, key=lambda q: math.dist(q, at)))
                    elif i:
                        target = c + np.array([(-1) ** i * 1.2 * i, 0.0])
                    # a small nook may have no spot that clears everything: say so in the zone list rather than force one in
                    placed_any = put(kind, zone_id, zone, target, rule, required=False) is not None or placed_any
            if placed_any:
                add_zone(zone_id, name.title(), rule, zone, air, n, at)

    # ---------------------------------------------------------------- corridors and lobbies: an even spread over what's left
    rule = room_type("CORRIDOR", spec)
    spacing = V["corridor_spacing"]
    corridors = [s["poly"] for s in merged if any(room_type(n, spec) is rule for n in s["names"])]
    corridors += [s["poly"] for s in spaces if len(s["names"]) == 1 and room_type(s["names"][0], spec) is rule]
    rest = unary_union(corridors).difference(unary_union(taken) if taken else Polygon())
    inset = rest.buffer(-V["corridor_inset"])
    area = rest.area
    air = rule["ach_total"] * area * height / 3.6
    picked, n_kind = [], {"supply": 0, "return": 0}
    if not inset.is_empty:
        x0, y0, x1, y1 = inset.bounds
        step = 0.6
        cands = [(x, y) for y in np.arange(y0, y1, step) for x in np.arange(x0, x1, step)]
        cands = [c for c in cands if prep(inset).contains(Point(c))]
        for c in cands:
            if all(math.dist(c, p) >= spacing for p in picked):
                kind = "supply" if len(picked) % 2 == 0 else "return"
                local = Point(c).buffer(1.2).intersection(rest)
                if put(kind, "corridor", local, c, rule, required=False) is not None:
                    picked.append(c)
                    n_kind[kind] += 1
    zones.append({"id": "corridor", "name": "Corridors and lobbies", "type": rule["type"], "area_m2": round(area, 1), "air_ls": round(air), "grilles": n_kind, "label_at": None})

    unused = [o for i, o in enumerate(V.get("overrides", [])) if i not in used_overrides]
    if unused:
        raise SystemExit(f"ventilation.overrides: nothing placed these: {unused}")
    return {"vents": vents, "zones": zones}
